CREATE TABLE public.allowed_users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), email text NOT NULL UNIQUE CHECK (email = lower(trim(email))));
GRANT SELECT ON public.allowed_users TO authenticated; GRANT ALL ON public.allowed_users TO service_role;
ALTER TABLE public.allowed_users ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_allowed_user() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = '' AS $$ SELECT EXISTS (SELECT 1 FROM public.allowed_users WHERE email = lower(auth.jwt()->>'email')) AND auth.uid() IS NOT NULL $$;
REVOKE ALL ON FUNCTION public.is_allowed_user() FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.is_allowed_user() TO authenticated, service_role;
CREATE POLICY allowed_read ON public.allowed_users FOR SELECT TO authenticated USING (public.is_allowed_user());

CREATE TABLE public.strategy_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version_no int NOT NULL UNIQUE, valid_from timestamptz NOT NULL, change_note text, created_by uuid DEFAULT auth.uid());
GRANT SELECT, INSERT ON public.strategy_versions TO authenticated; GRANT ALL ON public.strategy_versions TO service_role;
ALTER TABLE public.strategy_versions ENABLE ROW LEVEL SECURITY;
CREATE POLICY allowed_read ON public.strategy_versions FOR SELECT TO authenticated USING (public.is_allowed_user());
CREATE POLICY allowed_insert ON public.strategy_versions FOR INSERT TO authenticated WITH CHECK (public.is_allowed_user() AND created_by = auth.uid());
CREATE TABLE public.positioning (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version_id uuid NOT NULL UNIQUE REFERENCES public.strategy_versions(id), position_line text, thesis text, concept_name text, concept_description text, audience text, differentiation text, known_for text, objective text);
GRANT SELECT, INSERT ON public.positioning TO authenticated; GRANT ALL ON public.positioning TO service_role;
ALTER TABLE public.positioning ENABLE ROW LEVEL SECURITY;
CREATE POLICY allowed_read ON public.positioning FOR SELECT TO authenticated USING (public.is_allowed_user());
CREATE POLICY allowed_insert ON public.positioning FOR INSERT TO authenticated WITH CHECK (public.is_allowed_user());
CREATE TABLE public.content_pillars (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version_id uuid NOT NULL REFERENCES public.strategy_versions(id), key text NOT NULL, name text NOT NULL, description text, target_share numeric, sort_order int NOT NULL, UNIQUE(version_id,key));
GRANT SELECT, INSERT ON public.content_pillars TO authenticated; GRANT ALL ON public.content_pillars TO service_role;
ALTER TABLE public.content_pillars ENABLE ROW LEVEL SECURITY;
CREATE POLICY allowed_read ON public.content_pillars FOR SELECT TO authenticated USING (public.is_allowed_user()); CREATE POLICY allowed_insert ON public.content_pillars FOR INSERT TO authenticated WITH CHECK (public.is_allowed_user());
CREATE TABLE public.ctas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version_id uuid NOT NULL REFERENCES public.strategy_versions(id), rank int NOT NULL CHECK(rank BETWEEN 1 AND 3), label text NOT NULL, destination text, measured_how text NOT NULL CHECK(measured_how IN ('measured','not yet measured','self-reported')), UNIQUE(version_id,rank));
GRANT SELECT, INSERT ON public.ctas TO authenticated; GRANT ALL ON public.ctas TO service_role;
ALTER TABLE public.ctas ENABLE ROW LEVEL SECURITY;
CREATE POLICY allowed_read ON public.ctas FOR SELECT TO authenticated USING (public.is_allowed_user()); CREATE POLICY allowed_insert ON public.ctas FOR INSERT TO authenticated WITH CHECK (public.is_allowed_user());
CREATE TABLE public.kpi_definitions (key text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), name text NOT NULL, goal_category text NOT NULL, description text, formula text, formula_version int NOT NULL DEFAULT 1, unit text, better_when text NOT NULL CHECK(better_when IN ('higher','lower')), kind text NOT NULL CHECK(kind IN ('measured','self-reported','estimate','not yet measured')), sources_needed text[] NOT NULL, sort_order int NOT NULL, is_north_star boolean NOT NULL DEFAULT false);
COMMENT ON COLUMN public.kpi_definitions.kind IS 'Includes not yet measured to preserve the existing newsletter KPI kind exactly.';
GRANT SELECT, INSERT ON public.kpi_definitions TO authenticated; GRANT ALL ON public.kpi_definitions TO service_role;
ALTER TABLE public.kpi_definitions ENABLE ROW LEVEL SECURITY;
CREATE POLICY allowed_read ON public.kpi_definitions FOR SELECT TO authenticated USING (public.is_allowed_user()); CREATE POLICY allowed_insert ON public.kpi_definitions FOR INSERT TO authenticated WITH CHECK (public.is_allowed_user());
CREATE TABLE public.kpi_targets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now(), version_id uuid NOT NULL REFERENCES public.strategy_versions(id), kpi_key text NOT NULL REFERENCES public.kpi_definitions(key), baseline_value numeric, baseline_label text, target_value numeric, target_by date, UNIQUE(version_id,kpi_key));
GRANT SELECT, INSERT ON public.kpi_targets TO authenticated; GRANT ALL ON public.kpi_targets TO service_role;
ALTER TABLE public.kpi_targets ENABLE ROW LEVEL SECURITY;
CREATE POLICY allowed_read ON public.kpi_targets FOR SELECT TO authenticated USING (public.is_allowed_user()); CREATE POLICY allowed_insert ON public.kpi_targets FOR INSERT TO authenticated WITH CHECK (public.is_allowed_user());
