GRANT SELECT ON public.period_summaries TO authenticated; GRANT ALL ON public.period_summaries TO service_role;
ALTER TABLE public.period_summaries ENABLE ROW LEVEL SECURITY; CREATE POLICY allowed_read ON public.period_summaries FOR SELECT TO authenticated USING (public.is_allowed_user());

CREATE FUNCTION public.reject_history_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$ BEGIN RAISE EXCEPTION '% is insert-only: % is forbidden', TG_TABLE_NAME, TG_OP USING ERRCODE='55000'; END $$;
REVOKE ALL ON FUNCTION public.reject_history_mutation() FROM PUBLIC;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['strategy_versions','positioning','content_pillars','ctas','kpi_definitions','kpi_targets','sources','source_capabilities','periods','metric_catalog','snapshots','account_metrics','follower_daily','post_observations','audience_observations','audience_checks','leads','kpi_values','period_summaries'] LOOP EXECUTE format('CREATE TRIGGER immutable_history BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.reject_history_mutation()',t); EXECUTE format('ALTER TABLE public.%I ENABLE ALWAYS TRIGGER immutable_history',t); END LOOP; END $$;
CREATE FUNCTION public.protect_post_fields() RETURNS trigger LANGUAGE plpgsql SET search_path = '' AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'posts: DELETE is forbidden' USING ERRCODE='55000'; END IF; IF (to_jsonb(NEW) - ARRAY['pillar_key','topic','named_person','concept','format','visual','link_position']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['pillar_key','topic','named_person','concept','format','visual','link_position']) THEN RAISE EXCEPTION 'posts: only tag columns may be updated' USING ERRCODE='55000'; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.protect_post_fields() FROM PUBLIC;
CREATE TRIGGER protect_posts BEFORE UPDATE OR DELETE ON public.posts FOR EACH ROW EXECUTE FUNCTION public.protect_post_fields(); ALTER TABLE public.posts ENABLE ALWAYS TRIGGER protect_posts;

CREATE VIEW public.current_snapshots WITH (security_invoker=true) AS SELECT DISTINCT ON (period_id,source_key) * FROM public.snapshots ORDER BY period_id,source_key,(completeness='complete') DESC,captured_at DESC,created_at DESC,id DESC;
GRANT SELECT ON public.current_snapshots TO authenticated, service_role;
CREATE INDEX snapshots_selection ON public.snapshots(period_id,source_key,completeness,captured_at DESC);
CREATE INDEX account_metrics_snapshot ON public.account_metrics(snapshot_id);
CREATE INDEX follower_daily_snapshot ON public.follower_daily(snapshot_id);
CREATE INDEX post_observations_snapshot ON public.post_observations(snapshot_id);
CREATE INDEX audience_observations_snapshot ON public.audience_observations(snapshot_id);
CREATE INDEX audience_checks_snapshot ON public.audience_checks(snapshot_id);
CREATE INDEX leads_snapshot ON public.leads(snapshot_id);
CREATE INDEX kpi_values_period ON public.kpi_values(period_id,kpi_key);
CREATE INDEX period_summaries_period ON public.period_summaries(period_id);
CREATE INDEX run_steps_run ON public.run_steps(run_id);
CREATE INDEX data_quality_issues_run ON public.data_quality_issues(run_id);

CREATE FUNCTION public.commit_snapshot(payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $$
DECLARE s public.snapshots; r public.agent_runs; row_data jsonb; table_name text; insert_cols text; select_cols text; final_status text; written int := 1; affected int;
BEGIN
 IF current_user <> 'service_role' THEN RAISE EXCEPTION 'Only service_role may commit snapshots' USING ERRCODE='42501'; END IF;
 IF jsonb_typeof(payload) IS DISTINCT FROM 'object' OR jsonb_typeof(payload->'snapshot') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'payload.snapshot must be an object'; END IF;
 s := jsonb_populate_record(NULL::public.snapshots,payload->'snapshot');
 s.id := COALESCE(s.id,gen_random_uuid()); s.created_at := COALESCE(s.created_at,now());
 final_status := payload->>'final_status';
 IF final_status IS NULL OR final_status NOT IN ('succeeded','partial','failed','needs_attention') THEN RAISE EXCEPTION 'Invalid final_status'; END IF;
 SELECT * INTO r FROM public.agent_runs WHERE id=s.run_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'agent_runs row not found'; END IF;
 IF r.status NOT IN ('running','waiting_for_data') THEN RAISE EXCEPTION 'Run is already finalized'; END IF;
 IF r.period_id IS DISTINCT FROM s.period_id THEN RAISE EXCEPTION 'Snapshot period must match the run period'; END IF;
 IF s.supersedes_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM public.snapshots old WHERE old.id=s.supersedes_id AND old.period_id=s.period_id AND old.source_key=s.source_key) THEN RAISE EXCEPTION 'Superseded snapshot must match period and source'; END IF;
 FOR row_data IN SELECT value FROM jsonb_array_elements(COALESCE(payload->'posts','[]'::jsonb)) LOOP
  INSERT INTO public.posts(urn,published_at,url,format,hook,length_chars,visual,link_position,pillar_key,topic,named_person,concept,content_item_id)
  SELECT urn,published_at,url,format,hook,length_chars,visual,link_position,pillar_key,topic,named_person,concept,content_item_id FROM jsonb_populate_record(NULL::public.posts,row_data)
  ON CONFLICT(urn) DO UPDATE SET pillar_key=EXCLUDED.pillar_key,topic=EXCLUDED.topic,named_person=EXCLUDED.named_person,concept=EXCLUDED.concept,format=EXCLUDED.format,visual=EXCLUDED.visual,link_position=EXCLUDED.link_position;
  written := written+1;
 END LOOP;
 INSERT INTO public.snapshots SELECT s.*;
 FOREACH table_name IN ARRAY ARRAY['account_metrics','follower_daily','post_observations','audience_observations','audience_checks','leads','kpi_values','period_summaries'] LOOP
  IF payload ? table_name AND jsonb_typeof(payload->table_name) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION '% must be an array',table_name; END IF;
  SELECT string_agg(quote_ident(a.attname),',' ORDER BY a.attnum), string_agg(CASE a.attname WHEN 'id' THEN 'COALESCE(x.id,gen_random_uuid())' WHEN 'created_at' THEN 'COALESCE(x.created_at,now())' WHEN 'snapshot_id' THEN '$2' WHEN 'run_id' THEN '$3' WHEN 'period_id' THEN '$4' ELSE 'x.'||quote_ident(a.attname) END,',' ORDER BY a.attnum)
  INTO insert_cols,select_cols FROM pg_catalog.pg_attribute a WHERE a.attrelid=format('public.%I',table_name)::regclass AND a.attnum>0 AND NOT a.attisdropped;
  EXECUTE format('INSERT INTO public.%I (%s) SELECT %s FROM jsonb_populate_recordset(NULL::public.%I,$1) x',table_name,insert_cols,select_cols,table_name) USING COALESCE(payload->table_name,'[]'::jsonb),s.id,s.run_id,s.period_id;
  GET DIAGNOSTICS affected=ROW_COUNT; written := written+affected;
 END LOOP;
 UPDATE public.agent_runs SET status=final_status,finished_at=now(),duration_ms=CASE WHEN started_at IS NULL THEN NULL ELSE (extract(epoch FROM (now()-started_at))*1000)::bigint END,records_read=COALESCE((payload->>'records_read')::int,r.records_read),records_written=written,error_count=COALESCE((payload->>'error_count')::int,0),changes_summary=payload->>'changes_summary' WHERE id=s.run_id;
 RETURN s.id;
END $$;
REVOKE ALL ON FUNCTION public.commit_snapshot(jsonb) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.commit_snapshot(jsonb) TO service_role;